import json
import tempfile
import unittest
from pathlib import Path

from update_stars import FetchError, fetch_stars, render, update

HEADER = (
    '<!--lint disable awesome-contributing awesome-license awesome-list-item match-punctuation '
    'no-repeat-punctuation no-undefined-references awesome-spell-check-->\n'
    '# Awesome Stars [![Awesome](https://awesome.re/badge.svg)](https://github.com/sindresorhus/awesome)\n'
    '\n'
    '> A curated list of my GitHub stars! Generated by [starred](https://github.com/maguowei/starred).\n'
    '\n'
    '## Contents\n'
    '\n'
)

FOOTER = (
    '\n'
    '## License\n'
    '\n'
    '[![CC0](http://mirrors.creativecommons.org/presskit/buttons/88x31/svg/cc-zero.svg)]'
    '(https://creativecommons.org/publicdomain/zero/1.0/)\n'
    '\n'
    'To the extent possible under law, [me](https://github.com/me) '
    'has waived all copyright and related or neighboring rights to this work.\n'
    '\n'
)


def node(name, language=None, topics=(), description='Desc', private=False):
    return {
        'nameWithOwner': name,
        'url': f'https://github.com/{name}',
        'description': description,
        'isPrivate': private,
        'languages': {'edges': [{'node': {'name': language}}] if language else []},
        'repositoryTopics': {
            'nodes': [{'topic': {'name': t, 'stargazerCount': stars}} for t, stars in topics]
        },
    }


class RenderByLanguage(unittest.TestCase):
    def test_groups_by_language_sorted_keeping_star_order(self):
        nodes = [
            node('a/py2', 'Python'),
            node('a/c', 'C#'),
            node('a/py1', 'Python', description=None),
            node('a/none'),
        ]

        expected = HEADER + (
            '- [C#](#c#)\n'
            '- [Others](#others)\n'
            '- [Python](#python)\n'
            '\n'
            '## C# # \n'
            '\n'
            '- [a/c](https://github.com/a/c) - Desc\n'
            '\n'
            '## Others \n'
            '\n'
            '- [a/none](https://github.com/a/none) - Desc\n'
            '\n'
            '## Python \n'
            '\n'
            '- [a/py2](https://github.com/a/py2) - Desc\n'
            '- [a/py1](https://github.com/a/py1) - \n'
            '\n'
        ) + FOOTER

        self.assertEqual(render(nodes, 'me').decode(), expected)


class RenderRules(unittest.TestCase):
    def test_by_topic_keeps_popular_topics_and_falls_back_to_others(self):
        nodes = [
            node('a/both', 'Go', topics=[('cli', 501), ('rare', 500)]),
            node('a/multi', topics=[('cli', 900), ('web', 900)]),
            node('a/unpopular', topics=[('rare', 3)]),
        ]

        expected = HEADER + (
            '- [cli](#cli)\n'
            '- [others](#others)\n'
            '- [web](#web)\n'
            '\n'
            '## cli \n'
            '\n'
            '- [a/both](https://github.com/a/both) - Desc\n'
            '- [a/multi](https://github.com/a/multi) - Desc\n'
            '\n'
            '## others \n'
            '\n'
            '- [a/unpopular](https://github.com/a/unpopular) - Desc\n'
            '\n'
            '## web \n'
            '\n'
            '- [a/multi](https://github.com/a/multi) - Desc\n'
            '\n'
        ) + FOOTER

        self.assertEqual(render(nodes, 'me', by_topic=True).decode(), expected)

    def test_skips_private_repositories(self):
        output = render([node('a/secret', 'Go', private=True), node('a/open', 'Go')], 'me')

        self.assertNotIn(b'a/secret', output)
        self.assertIn(b'a/open', output)

    def test_sanitizes_descriptions(self):
        description = '  <b>\nx' + 'y' * 300
        output = render([node('a/r', 'Go', description=description)], 'me').decode()

        # Escaping and newline removal happen before stripping and truncating to 200 chars.
        expected = '&lt;b&gt;x' + 'y' * 190
        self.assertIn(f'- [a/r](https://github.com/a/r) - {expected}\n', output)


def page(nodes, next_cursor=None):
    body = {
        'data': {
            'user': {
                'starredRepositories': {
                    'nodes': nodes,
                    'pageInfo': {'endCursor': next_cursor, 'hasNextPage': next_cursor is not None},
                }
            }
        }
    }
    return 200, {}, json.dumps(body).encode()


class FakeGitHub:
    """Replays scripted answers; an exception instance is raised instead of returned."""

    def __init__(self, *answers):
        self.answers = list(answers)
        self.variables = []

    def __call__(self, variables):
        self.variables.append(variables)
        answer = self.answers.pop(0)
        if isinstance(answer, Exception):
            raise answer
        return answer


class FetchStars(unittest.TestCase):
    def setUp(self):
        self.sleeps = []

    def fetch(self, github):
        return fetch_stars('me', github, sleep=self.sleeps.append)

    def test_follows_cursors_until_the_last_page(self):
        github = FakeGitHub(page([{'id': 1}], 'c1'), page([{'id': 2}]))

        self.assertEqual(self.fetch(github), [{'id': 1}, {'id': 2}])
        self.assertEqual([v['after'] for v in github.variables], [None, 'c1'])
        self.assertEqual(self.sleeps, [])

    def test_retries_gateway_errors_and_network_failures_on_the_same_page(self):
        github = FakeGitHub(
            page([{'id': 1}], 'c1'),
            (502, {}, b'<html>Bad Gateway</html>'),
            TimeoutError(),
            page([{'id': 2}]),
        )

        self.assertEqual(self.fetch(github), [{'id': 1}, {'id': 2}])
        self.assertEqual([v['after'] for v in github.variables], [None, 'c1', 'c1', 'c1'])
        self.assertEqual(self.sleeps, [5, 10])

    def test_retries_graphql_errors_and_invalid_json(self):
        github = FakeGitHub(
            (200, {}, json.dumps({'errors': [{'message': 'timeout'}]}).encode()),
            (200, {}, b'not json'),
            page([{'id': 1}]),
        )

        self.assertEqual(self.fetch(github), [{'id': 1}])
        self.assertEqual(self.sleeps, [5, 10])

    def test_rate_limit_honours_retry_after(self):
        github = FakeGitHub((403, {'Retry-After': '120'}, b'{}'), page([]))

        self.assertEqual(self.fetch(github), [])
        self.assertEqual(self.sleeps, [120])

    def test_rate_limit_without_header_waits_at_least_a_minute(self):
        github = FakeGitHub((403, {}, b'{}'), (429, {}, b'{}'), page([]))

        self.assertEqual(self.fetch(github), [])
        self.assertEqual(self.sleeps, [60, 60])

    def test_gives_up_after_max_attempts(self):
        github = FakeGitHub(*[(502, {}, b'')] * 8)

        with self.assertRaisesRegex(FetchError, '502'):
            self.fetch(github)
        self.assertEqual(len(github.variables), 8)
        self.assertEqual(self.sleeps, [5, 10, 20, 40, 80, 160, 300])

    def test_bad_credentials_fail_immediately(self):
        github = FakeGitHub((401, {}, b'{"message": "Bad credentials"}'))

        with self.assertRaisesRegex(FetchError, '401'):
            self.fetch(github)
        self.assertEqual(self.sleeps, [])


class Update(unittest.TestCase):
    def test_writes_both_files(self):
        github = FakeGitHub(page([node('a/r', 'Go', topics=[('cli', 900)])]))
        with tempfile.TemporaryDirectory() as directory:
            update('me', github, Path(directory), sleep=lambda _: None)

            readme = (Path(directory) / 'README.md').read_text()
            topics = (Path(directory) / 'topics.md').read_text()
        self.assertIn('## Go \n', readme)
        self.assertIn('## cli \n', topics)

    def test_failure_leaves_existing_files_untouched(self):
        github = FakeGitHub(page([], 'c1'), (401, {}, b''))
        with tempfile.TemporaryDirectory() as directory:
            readme = Path(directory) / 'README.md'
            readme.write_text('previous')

            with self.assertRaises(FetchError):
                update('me', github, Path(directory), sleep=lambda _: None)

            self.assertEqual(readme.read_text(), 'previous')
            self.assertFalse((Path(directory) / 'topics.md').exists())


if __name__ == '__main__':
    unittest.main()
